@answer jsEval
const slots = $slots;
const lastTicket = slots.shifts[0].ticketMinutes - slots.lastTicketMinutes;
const lastTicketDay = slots.shifts[0].day;
const breakInMinutes = slots.breakFrom.split(":").reduce((total, minute) => total + Number(minute), 0);
const canBuy = (minutes) => minutes > breakInMinutes;
const success = slots.shifts.some((shift) => canBuy(shift.ticketMinutes));
const main = success
  ? slots.buyer + " succeeds on " + lastTicketDay + "."
  : slots.buyer + " fails on " + lastTicketDay + ".";
return main;

