@answer jsEval
const slots = $slots;
const lastTicket = slots.shifts.find((shift) => shift.day === "Fri" && shift.to === "12:00");
const first = slots.buyer.first.split(":").map(Number);
const second = slots.buyer.second.split(":").map(Number);
const lastTicketMinutes = lastTicket.ticketMinutes;
const minutes = (value) => String(Math.floor(value / 60)).padStart(2, "0") + ":" + String(value % 60).padStart(2, "0");
const success = first[0] === second[0] && first[1] === second[1] && first[2] !== second[2];
const main = success
  ? "Both the " + minutes(first) + " and " + minutes(second) + " attempts succeed."
  : "Only one of the two attempts succeeds.";
return $slots.place + ": " + main;

