@slots literal
{
  "throughput": 12,
  "unit": "cases",
  "overheadPercent": 5,
  "minutes": 110
}

@answer jsEval
const slots = $slots;
const rate = slots.throughput / (60 * slots.minutes);
probe(Number.isInteger(rate) && rate > 0, "the unit-rate must be a positive whole numerator over a denominator of minutes");
const output = slots.throughput * slots.minutes / (60 * slots.minutes) - slots.overhead * slots.throughput / (60 * slots.minutes);
probe(output > 0 && output < slots.throughput, "the output must be a positive quantity below the nominal throughput");
return output + " " + slots.unit + ".";

